class DayRepositoryImpl @Inject constructor(
    private val dayDao: DayDao
) : DayRepository {
    override fun getAllDays(): Flow<List<Day>> {
        return dayDao.getAllDays().map { list -> list.map { it.toDomainModel() } }
    }

    override fun getDaysByMonth(month: Int): Flow<List<Day>> {
        return dayDao.getDaysByMonth(month).map { list -> list.map { it.toDomainModel() } }
    }

    override suspend fun getDayById(id: Int): Day? {
        return dayDao.getDayById(id)?.toDomainModel()
    }

    override fun searchDays(query: String): Flow<List<Day>> {
        return dayDao.searchDays(query).map { list -> list.map { it.toDomainModel() } }
    }

    override fun getFavoriteDays(): Flow<List<Day>> {
        return dayDao.getFavoriteDays().map { list -> list.map { it.toDomainModel() } }
    }

    override suspend fun insertDay(day: Day) {
        dayDao.insertDay(day.toEntity())
    }

    override suspend fun insertDays(days: List<Day>) {
        dayDao.insertDays(days.map { it.toEntity() })
    }

    override suspend fun updateDay(day: Day) {
        dayDao.updateDay(day.toEntity())
    }

    override suspend fun deleteDay(day: Day) {
        dayDao.deleteDay(day.toEntity())
    }

