            DayEntity(title = "National Safety Day", category = "National (India)", description = "Promotes workplace and industrial safety. Observed by the National Safety Council of India. It launches the National Safety Week campaign.", month = 3, day = 4),
            DayEntity(title = "CISF Raising Day", category = "National (India)", description = "Marks the founding of the Central Industrial Security Force. Important for security and public infrastructure protection in India. CISF was set up in 1969 with a strength of just 3,129 personnel.", month = 3, day = 10),
            DayEntity(title = "Dandi March Anniversary", category = "Historical", description = "Anniversary of the Salt March led by Mahatma Gandhi. The Dandi March began on 12 March 1930, a major nonviolent protest in the freedom struggle. Gandhi walked 240 miles to produce salt without paying the British tax.", month = 3, day = 12),
            DayEntity(title = "Mauritius Day", category = "International", description = "Important for world history and Indian Ocean relations. Marks both the independence of Mauritius (1968) and its transition to a republic (1992). Mauritius has a large population of Indian descent.", month = 3, day = 12),
            DayEntity(title = "Pi Day", category = "Science", description = "Celebrates the mathematical constant Pi. Popular in science and math awareness. It is also the birthday of Albert Einstein and the death anniversary of Stephen Hawking.", month = 3, day = 14),
            DayEntity(title = "International Day of Action for Rivers", category = "Environmental", description = "Highlights river protection, dam impacts, and water rights. Adopted in 1997 during the first International Meeting of People Affected by Dams. Dedicated to protecting free-flowing rivers.", month = 3, day = 14),
            DayEntity(title = "World Consumer Rights Day", category = "International", description = "Important for consumer protection, market fairness, and legal rights. Became prominent after US President John F. Kennedy's 1962 consumer rights speech. First observed in 1983.", month = 3, day = 15),
            DayEntity(title = "National Vaccination Day", category = "National (India)", description = "Recognizes vaccination efforts in India, especially the Pulse Polio program. A very relevant public health and immunization day in India. The first dose of an oral polio vaccine was given in India on this day in 1995.", month = 3, day = 16),
            DayEntity(title = "Ordnance Factories Day", category = "National (India)", description = "Marks the contribution of ordnance factories to defence production and self-reliance. Useful for defence and industrial policy awareness. The first Ordnance Factory in India was established at Cossipore in 1801.", month = 3, day = 18),
            DayEntity(title = "World Sparrow Day", category = "Environmental", description = "Raises awareness about sparrow conservation and urban biodiversity. Focuses on the declining population of house sparrows in urban areas. Initiated by the Nature Forever Society of India.", month = 3, day = 20),
            DayEntity(title = "International Day of Forests", category = "Environmental", description = "Focuses on forest conservation, climate, and biodiversity. Established by the UN to raise awareness of the importance of all types of forests. Forests cover one third of the Earth's land mass.", month = 3, day = 21),
            DayEntity(title = "World Down Syndrome Day", category = "Health", description = "Promotes inclusion, rights, and well-being of people with Down syndrome. March 21 (21/3) signifies the triplication of the 21st chromosome. People wear mismatched socks to raise awareness.", month = 3, day = 21),
            DayEntity(title = "World Poetry Day", category = "Cultural", description = "Celebrates poetry as a cultural and creative expression. Declared by UNESCO to support linguistic diversity through poetic expression. Aims to return to the oral tradition of poetry recitals.", month = 3, day = 21),
            DayEntity(title = "Bihar Day", category = "National (India)", description = "Marks the creation of Bihar as a separate province in 1912. Carved out of the Bengal Presidency by the British. It is a public holiday in the state of Bihar.", month = 3, day = 22),
            DayEntity(title = "World Meteorological Day", category = "Science", description = "Commemorates the entry into force of the WMO Convention. Highlights the contribution of National Meteorological and Hydrological Services. Crucial for understanding climate change and weather patterns.", month = 3, day = 23),
            DayEntity(title = "World Tuberculosis Day", category = "Health", description = "Very important for public health, disease control, and India's TB elimination efforts. Marks Dr. Robert Koch's announcement of the TB bacillus in 1882. India has a goal to eliminate TB by 2025, five years ahead of the global target.", month = 3, day = 24),
            DayEntity(title = "Purple Day for Epilepsy", category = "Health", description = "Promotes understanding of epilepsy, treatment, and stigma reduction. A grassroots effort dedicated to increasing awareness about epilepsy worldwide. People are encouraged to wear purple.", month = 3, day = 26),
            DayEntity(title = "World Theatre Day", category = "Cultural", description = "Celebrates theatre, performing arts, and artistic expression. Initiated by the International Theatre Institute (ITI). A prominent figure in theatre delivers a global message every year.", month = 3, day = 27),
            DayEntity(title = "Rajasthan Day", category = "National (India)", description = "Marks the formation of Rajasthan in 1949. Useful state foundation date for Indian polity and history. Formed when the Rajputana states were merged into the Dominion of India.", month = 3, day = 30),
            DayEntity(title = "International Transgender Day of Visibility", category = "Human Rights", description = "Important gender and social inclusion observance. Dedicated to celebrating transgender people and raising awareness of discrimination. Founded by transgender activist Rachel Crandall in 2009.", month = 3, day = 31),
            DayEntity(title = "Labour Day (International Workers' Day)", category = "International", description = "Recognizes workers' rights, labour movements, and fair working conditions. Promoted by the international labour movement globally. Also known as May Day.", month = 5, day = 1),
            DayEntity(title = "Maharashtra Day & Gujarat Day", category = "National (India)", description = "Marks the formation of the states of Maharashtra and Gujarat. Both states were created from the Bombay State in 1960. It is a public holiday in both states.", month = 5, day = 1),
            DayEntity(title = "Coal Miners Day", category = "National (India)", description = "Honors the contribution of coal miners to India's energy sector. Recognizes the difficult and dangerous work of coal mining. The first coal mine in India was opened in 1774.", month = 5, day = 4),
            DayEntity(title = "International Firefighters' Day", category = "International", description = "Recognizes firefighters and their role in disaster response and public safety. Instituted after a tragic bushfire in Australia in 1998. The symbol is a red and blue ribbon.", month = 5, day = 4),
            DayEntity(title = "World Hand Hygiene Day", category = "Health", description = "Promotes simple but effective infection prevention through handwashing. An initiative by the World Health Organization (WHO). Aimed at maintaining global promotion of hand hygiene in health care.", month = 5, day = 5),
            DayEntity(title = "African World Heritage Day", category = "International", description = "Celebrates Africa's cultural and natural heritage. Proclaimed by UNESCO to raise awareness of African heritage. Africa is underrepresented on the World Heritage List.", month = 5, day = 5),
            DayEntity(title = "World Athletics Day", category = "International", description = "Encourages sports participation and fitness among youth. Introduced by the IAAF to promote athletics in schools. Celebrated as part of the IAAF's social responsibility project.", month = 5, day = 7),
            DayEntity(title = "World Red Cross Day", category = "Health", description = "Marks the birth anniversary of Henry Dunant, founder of the Red Cross. Celebrates the principles of the International Red Cross and Red Crescent Movement. Henry Dunant was the first recipient of the Nobel Peace Prize.", month = 5, day = 8),
            DayEntity(title = "World Thalassaemia Day", category = "Health", description = "Raises awareness about thalassaemia, a genetic blood disorder. Focuses on patient care and prevention of the disease. Thalassaemia causes the body to have less hemoglobin than normal.", month = 5, day = 8),
            DayEntity(title = "Victory Day in Europe", category = "Historical", description = "Marks the end of World War II in Europe. Very useful for world history and international relations. It marks the formal acceptance by the Allies of Nazi Germany's unconditional surrender.", month = 5, day = 9),
            DayEntity(title = "World Lupus Day", category = "Health", description = "Spreads awareness about lupus, an autoimmune disease. Aimed at improving patient healthcare services for lupus. The symbol for lupus awareness is a purple ribbon or a butterfly.", month = 5, day = 10),
            DayEntity(title = "National Technology Day", category = "Science", description = "Commemorates India's successful Pokhran nuclear tests in 1998. A very important science and technology date for UPSC. The operation was code-named Operation Shakti.", month = 5, day = 11),
            DayEntity(title = "International Nurses Day", category = "Health", description = "Celebrates the contribution of nurses globally. Observed on the birth anniversary of Florence Nightingale, the founder of modern nursing. Organized annually by the International Council of Nurses.", month = 5, day = 12),
            DayEntity(title = "International Day of Families", category = "International", description = "Focuses on the role of families in society and development. Highlights the importance of families as basic units of society. Proclaimed by the UN General Assembly in 1993.", month = 5, day = 15),
            DayEntity(title = "National Endangered Species Day", category = "Environmental", description = "Promotes wildlife conservation. Raises awareness about the need to protect endangered species and their habitats. Observed on the third Friday of May.", month = 5, day = 15),
            DayEntity(title = "National Dengue Day", category = "Health", description = "Raises awareness about dengue prevention, mosquito control, and public health. Important for health-related current affairs and disease control in India. Initiated by the Ministry of Health and Family Welfare.", month = 5, day = 16),
            DayEntity(title = "World Telecommunication and Information Society Day", category = "Technology", description = "Promotes digital communication and information access. Marks the founding of the International Telecommunication Union (ITU). Raises awareness of the possibilities that the internet brings to societies.", month = 5, day = 17),
            DayEntity(title = "World Hypertension Day", category = "Health", description = "Spreads awareness about high blood pressure and lifestyle diseases. Crucial for preventing strokes, heart disease, and kidney diseases. Hypertension is often called a 'silent killer'.", month = 5, day = 17),
            DayEntity(title = "International Museum Day", category = "Cultural", description = "Highlights museums as centers of culture, education, heritage, and research. Very useful for culture and history questions. Organized by the International Council of Museums (ICOM).", month = 5, day = 18),
            DayEntity(title = "World Bee Day", category = "Environmental", description = "Promotes bees, pollination, biodiversity, and sustainable agriculture. An important environment and farming-related observance. May 20 is the birthday of Anton Janša, the pioneer of modern apiculture.", month = 5, day = 20),
            DayEntity(title = "National Anti-Terrorism Day", category = "National (India)", description = "Observed in India to promote peace and unity. Remembers the assassination of former Prime Minister Rajiv Gandhi in 1991. A notable civic and political awareness day.", month = 5, day = 21),
            DayEntity(title = "World Turtle Day", category = "Environmental", description = "Spreads awareness about turtle and tortoise conservation. Aimed at helping people celebrate and protect turtles and their disappearing habitats. Sponsored by the American Tortoise Rescue.", month = 5, day = 23),
            DayEntity(title = "Africa Day", category = "International", description = "Marks the founding of the Organization of African Unity (OAU). Celebrates African unity and progress. The OAU was founded in 1963 and later became the African Union.", month = 5, day = 25),
            DayEntity(title = "Missing Children's Day", category = "Human Rights", description = "Raises awareness about child safety and protection. A day to remember missing children and encourage efforts to find them. The forget-me-not flower is the symbol for missing children.", month = 5, day = 25),
            DayEntity(title = "Menstrual Hygiene Day", category = "Health", description = "Focuses on menstrual health, dignity, and sanitation. Breaks the silence and builds awareness about the fundamental role of good menstrual hygiene management. May 28 was chosen because the average menstrual cycle is 28 days long.", month = 5, day = 28),
            DayEntity(title = "International Day of UN Peacekeepers", category = "International", description = "Honors UN peacekeepers and their role in global peace and conflict resolution. Important for international relations and global governance. More than one million men and women have served under the UN flag.", month = 5, day = 29),
            DayEntity(title = "World Milk Day", category = "International", description = "Highlights the nutritional value of milk and the dairy sector. Established by the Food and Agriculture Organization (FAO) of the UN. India is the largest producer of milk globally.", month = 6, day = 1),
            DayEntity(title = "Global Day of Parents", category = "International", description = "Recognizes the primary role of parents in the rearing and protection of children. Proclaimed by the UN General Assembly in 2012. Appreciates all parents in all parts of the world for their selfless commitment.", month = 6, day = 1),
            DayEntity(title = "Telangana Formation Day", category = "National (India)", description = "Marks the creation of the state of Telangana. Telangana was officially formed on June 2, 2014, as the 29th state of India. Carved out of the ten north-western districts of Andhra Pradesh.", month = 6, day = 2),
            DayEntity(title = "International Sex Workers' Day", category = "Human Rights", description = "Focuses on rights, safety, and dignity in a highly sensitive social context. Commemorates the 1975 occupation of Saint-Nizier Church in France by sex workers protesting criminalization. Also known as International Whore's Day.", month = 6, day = 2),
            DayEntity(title = "World Bicycle Day", category = "Environmental", description = "Promotes cycling as a healthy, eco-friendly, and sustainable mode of transport. Relevant to environment, urban mobility, and public health. Adopted by the UN General Assembly in 2018.", month = 6, day = 3),
            DayEntity(title = "International Day of Innocent Children Victims of Aggression", category = "Human Rights", description = "Draws attention to children affected by violence, war, and abuse. Important for human rights and conflict studies globally. Originally established focusing on victims of the 1982 Lebanon War.", month = 6, day = 4),
            DayEntity(title = "D-Day Anniversary", category = "Historical", description = "Remembers the Normandy landings of 1944. A major turning point in World War II that led to the liberation of Europe. The largest seaborne invasion in history.", month = 6, day = 6),
            DayEntity(title = "World Food Safety Day", category = "Health", description = "Focuses on safe food handling, contamination prevention, and public health. Important for food security, economic prosperity, and sustainable development. Jointly facilitated by the WHO and the FAO.", month = 6, day = 7),
            DayEntity(title = "World Brain Tumour Day", category = "Health", description = "Raises awareness about brain tumours and neurological health. Aims to draw attention to this often-fatal disease and support patients and their families. Initiated by the German Brain Tumour Association.", month = 6, day = 8),
            DayEntity(title = "World Day Against Child Labour", category = "Human Rights", description = "A major UN day to end child labour and protect children's rights. Important for social justice, labour law, and child welfare. Launched by the International Labour Organization (ILO) in 2002.", month = 6, day = 12),
            DayEntity(title = "International Albinism Awareness Day", category = "Human Rights", description = "Raises awareness about albinism and advocates for inclusion. Focuses on fighting discrimination and improving access to healthcare for people with albinism. Albinism is a rare, non-contagious, genetically inherited condition.", month = 6, day = 13),
            DayEntity(title = "World Elder Abuse Awareness Day", category = "Human Rights", description = "Draws attention to violence, neglect, and the rights of older people. Highlights the need for appropriate policies and social protections for seniors. Initiated by the International Network for the Prevention of Elder Abuse.", month = 6, day = 15),
            DayEntity(title = "World Wind Day", category = "Environmental", description = "Promotes wind energy and renewable power. Discovering the power of wind energy and the possibilities it holds to reshape our energy systems. Coordinated by WindEurope and the Global Wind Energy Council.", month = 6, day = 15),
            DayEntity(title = "World Day to Combat Desertification and Drought", category = "Environmental", description = "A key environment day focused on sustainable land management. Very important for UPSC environment and geography topics regarding land degradation. Promotes public awareness of international efforts to combat desertification.", month = 6, day = 17),
            DayEntity(title = "Autistic Pride Day", category = "Human Rights", description = "Celebrates neurodiversity and the rights of autistic people. A social awareness day emphasizing that autism is a difference rather than a disease. Represented by the infinity symbol.", month = 6, day = 18),
            DayEntity(title = "World Sickle Cell Awareness Day", category = "Health", description = "Focuses on sickle cell disease, genetic health, and public health. Useful for medical and tribal health questions, highlighting the need for early diagnosis. Sickle cell disease is a major genetic disease affecting red blood cells.", month = 6, day = 19),
            DayEntity(title = "World Music Day (Fête de la Musique)", category = "Cultural", description = "Celebrates music and artistic expression. Encourages amateur and professional musicians to perform in the streets. Originated in France in 1982.", month = 6, day = 21),
            DayEntity(title = "World Hydrography Day", category = "Science", description = "Important for oceans, mapping, and navigation. Highlights the work of hydrographers and the importance of hydrography. Adopted by the International Hydrographic Organization (IHO).", month = 6, day = 21),
            DayEntity(title = "World Rainforest Day", category = "Environmental", description = "Promotes rainforest conservation and biodiversity protection. A critical climate and environment-related observance to combat deforestation. Rainforests are often called the 'lungs of the Earth'.", month = 6, day = 22),
            DayEntity(title = "United Nations Public Service Day", category = "International", description = "Honors the role of public servants in development and governance. Celebrates the value and virtue of public service to the community. The UN Public Service Awards are given on this day.", month = 6, day = 23),
            DayEntity(title = "International Olympic Day", category = "International", description = "Celebrates the modern Olympic movement. Commemorates the founding of the International Olympic Committee (IOC) in 1894. Promotes mass participation in sports globally.", month = 6, day = 23),
            DayEntity(title = "International Widow's Day", category = "Human Rights", description = "Highlights the rights and hardships of widows. Addresses the poverty and injustice faced by millions of widows and their dependents. Initiated by the Loomba Foundation.", month = 6, day = 23),
            DayEntity(title = "Day of the Seafarer", category = "International", description = "Recognizes seafarers and their contribution to global trade and shipping. Useful for economy and maritime studies. An official United Nations international observance day.", month = 6, day = 25),
            DayEntity(title = "International Day Against Drug Abuse and Illicit Trafficking", category = "Health", description = "A major UN observance against drug abuse and trafficking. Aims to strengthen action and cooperation to achieve a society free of drug abuse. Supported by the UN Office on Drugs and Crime (UNODC).", month = 6, day = 26),
            DayEntity(title = "International Day in Support of Victims of Torture", category = "Human Rights", description = "Highlights human rights and support for torture survivors. Commemorates the UN Convention against Torture coming into effect. Aims to ensure the total eradication of torture globally.", month = 6, day = 26),
            DayEntity(title = "National Statistics Day", category = "National (India)", description = "Honors P. C. Mahalanobis and the importance of statistics in planning. Highlights the role of statistics in socio-economic planning and policy formulation in India. Prasanta Chandra Mahalanobis founded the Indian Statistical Institute.", month = 6, day = 29),
            DayEntity(title = "International Day of the Tropics", category = "Environmental", description = "Highlights tropical regions, climate, and development challenges. Raises awareness about specific challenges faced by tropical areas, such as climate change and poverty. The Tropics host nearly 95% of the world's mangrove forests.", month = 6, day = 29),
            DayEntity(title = "International Asteroid Day", category = "Science", description = "Promotes awareness of asteroids and planetary defense. Commemorates the Tunguska event of 1908, the Earth's largest recorded asteroid impact. Co-founded by astrophysicist and Queen guitarist Dr. Brian May.", month = 6, day = 30),
            DayEntity(title = "National Doctor's Day", category = "National (India)", description = "Honors doctors and marks the birth anniversary of Dr. B. C. Roy. Recognizes the contributions of physicians to individual lives and communities. Dr. Bidhan Chandra Roy was the second Chief Minister of West Bengal.", month = 7, day = 1),
            DayEntity(title = "Chartered Accountants' Day", category = "National (India)", description = "Marks the founding of the Institute of Chartered Accountants of India (ICAI). ICAI is the second largest professional accounting body in the world. Established by an Act of Parliament in 1949.", month = 7, day = 1),
            DayEntity(title = "National Postal Worker Day", category = "National (India)", description = "Recognizes the role of postal staff in communication and delivery services. Honors the hard work of postmen and delivery personnel. India has the largest postal network in the world.", month = 7, day = 1),
            DayEntity(title = "World UFO Day", category = "Science", description = "An awareness day about unidentified flying objects and the possibility of life beyond Earth. Commemorates the Roswell incident of 1947. Aimed at encouraging governments to declassify their files on UFO sightings.", month = 7, day = 2),
            DayEntity(title = "Independence Day of the United States", category = "Historical", description = "Marks the adoption of the Declaration of Independence in 1776. The United States declared independence from Great Britain. Commonly known as the Fourth of July.", month = 7, day = 4),
            DayEntity(title = "World Zoonoses Day", category = "Health", description = "Highlights diseases transmitted from animals to humans. Marks the first successful rabies vaccination by Louis Pasteur in 1885. About 60% of known infectious diseases in humans are transmitted from animals.", month = 7, day = 6),
            DayEntity(title = "World Rural Development Day", category = "International", description = "Focuses on rural livelihoods, inclusive growth, and village development. Promotes sustainable development in rural areas worldwide. Aimed at eradicating poverty and improving food security.", month = 7, day = 6),
            DayEntity(title = "World Kiswahili Language Day", category = "Cultural", description = "Promotes the language's cultural and international role. First African language to be recognized in such a manner by the UN. Kiswahili is spoken by over 200 million people.", month = 7, day = 7),
            DayEntity(title = "Global Forgiveness Day", category = "Human Rights", description = "Encourages reconciliation and peaceful coexistence. A day to forgive and be forgiven. Founded by the Christian Embassy of Christ's Ambassadors.", month = 7, day = 7),
            DayEntity(title = "National Fish Farmer's Day", category = "Agriculture", description = "A sector-specific observance linked to fisheries and aquaculture. Useful for agriculture and rural economy awareness in India. Commemorates Dr. H. L. Chaudhuri for his contribution to induced breeding of major carps.", month = 7, day = 10),
            DayEntity(title = "Day of Combating Sand and Dust Storms", category = "Environmental", description = "Highlights the environmental and economic impact of dust storms. Important for arid and semi-arid regions. Recognizes that sand and dust storms present a formidable challenge to sustainable development.", month = 7, day = 12),
            DayEntity(title = "Bastille Day", category = "Historical", description = "France's National Day. Commemorates the storming of the Bastille in 1789 and the beginning of the French Revolution. Formally called the Fête nationale française.", month = 7, day = 14),
            DayEntity(title = "World Youth Skills Day", category = "International", description = "Promotes skill development, employability, and vocational training for youth. Very relevant for India's demographic dividend and employment issues. Designated by the UN General Assembly in 2014.", month = 7, day = 15),
            DayEntity(title = "World Day for International Justice", category = "Human Rights", description = "Supports accountability for genocide, war crimes, and crimes against humanity. Commemorates the adoption of the Rome Statute in 1998. Unites all those who wish to support justice and promote victims' rights.", month = 7, day = 17),
            DayEntity(title = "International Moon Day", category = "Science", description = "Marks the first human landing on the Moon in 1969. Useful for science, space, and global exploration history. Commemorates the Apollo 11 lunar mission.", month = 7, day = 20),
            DayEntity(title = "Pi Approximation Day", category = "Science", description = "A math and science observance. The fraction 22/7 is a common approximation of Pi (π). Celebrated on July 22 since dates in the day/month format are 22/7.", month = 7, day = 22),
            DayEntity(title = "National Flag Adoption Day", category = "National (India)", description = "Marks the adoption of India's national flag. The tricolor was adopted in its present form on July 22, 1947. Designed by Pingali Venkayya.", month = 7, day = 22),
            DayEntity(title = "National Broadcasting Day", category = "National (India)", description = "Marks the start of regular radio broadcasting in India. The first radio broadcast was made from the Bombay Station in 1927. All India Radio (AIR) is one of the largest broadcasting organizations in the world.", month = 7, day = 23),
            DayEntity(title = "Chandra Shekhar Azad Jayanti", category = "Historical", description = "Birth anniversary of the revolutionary freedom fighter. Reorganized the Hindustan Republican Association into the HSRA. He famously vowed never to be captured alive by the British.", month = 7, day = 23),
            DayEntity(title = "Income Tax Day (Aaykar Diwas)", category = "National (India)", description = "Observed to mark the introduction of income tax in India. Income tax was introduced in India in 1860 by Sir James Wilson. Very important for economy and taxation awareness.", month = 7, day = 24),
            DayEntity(title = "International Tiger Day", category = "Environmental", description = "Promotes tiger conservation and protection of habitats. One of the most important environment and wildlife dates. Created in 2010 at the Saint Petersburg Tiger Summit.", month = 7, day = 29),
            DayEntity(title = "International Day of Friendship", category = "International", description = "Promotes peace and intercultural understanding. Recognizes the relevance of friendship as a noble and valuable sentiment. Proclaimed by the UN General Assembly in 2011.", month = 7, day = 30),
            DayEntity(title = "World Day Against Trafficking in Persons", category = "Human Rights", description = "Focuses on combating human trafficking and protecting victims. A critical human rights observance to stop the exploitation of individuals. Every country in the world is affected by human trafficking.", month = 7, day = 30),
            DayEntity(title = "World Ranger Day", category = "Environmental", description = "Honors park rangers and their role in wildlife protection. Commemorates rangers killed or injured in the line of duty. Promoted by the International Ranger Federation.", month = 7, day = 31),
            DayEntity(title = "World Lung Cancer Day", category = "Health", description = "Raises awareness about prevention, early detection, and treatment of lung cancer. Crucial for public health advocacy globally. Lung cancer is one of the most common cancers worldwide.", month = 8, day = 1),
            DayEntity(title = "World Wide Web Day", category = "Technology", description = "Marks the creation of the web and its impact on communication. Celebrates the way the internet has transformed the world. Tim Berners-Lee invented the World Wide Web in 1989.", month = 8, day = 1),
            DayEntity(title = "World Breastfeeding Week Begins", category = "Health", description = "Promotes maternal and child health. Coordinated by the World Alliance for Breastfeeding Action. Supported by WHO and UNICEF.", month = 8, day = 1),
            DayEntity(title = "National Handloom Day", category = "National (India)", description = "Celebrates India's handloom sector, artisans, and textile heritage. Marks the launch of the Swadeshi Movement in 1905. Very important for Indian culture and economy.", month = 8, day = 7),
            DayEntity(title = "International Day of the World's Indigenous Peoples", category = "Human Rights", description = "Protects the rights of the world's indigenous population. Recognizes the achievements and contributions that indigenous people make to improve world issues. Pronounced by the UN General Assembly in 1994.", month = 8, day = 9),
            DayEntity(title = "Nagasaki Day", category = "Historical", description = "Remembers the second atomic bombing in 1945. The US dropped the 'Fat Man' plutonium bomb on Nagasaki. It led to Japan's unconditional surrender in World War II.", month = 8, day = 9),
            DayEntity(title = "World Lion Day", category = "Environmental", description = "Promotes lion conservation and wildlife protection. Especially relevant for ecology and biodiversity. Lions are currently listed as 'Vulnerable' on the IUCN Red List.", month = 8, day = 10),
            DayEntity(title = "World Elephant Day", category = "Environmental", description = "Promotes elephant conservation and human-wildlife coexistence. Brings attention to the urgent plight of Asian and African elephants. Co-founded by Canadian filmmaker Patricia Sims.", month = 8, day = 12),
            DayEntity(title = "World Organ Donation Day", category = "Health", description = "Spreads awareness about organ donation and transplantation. Encourages people to pledge to donate organs after death. One organ donor can save up to eight lives.", month = 8, day = 13),
            DayEntity(title = "International Left-Handers Day", category = "Cultural", description = "Celebrates the uniqueness and differences of left-handed individuals. Raises awareness of the advantages and disadvantages of being left-handed in a predominantly right-handed world. Roughly 10% of the world's population is left-handed.", month = 8, day = 13),
            DayEntity(title = "Partition Horrors Remembrance Day", category = "National (India)", description = "Remembers the suffering caused by Partition in 1947. Acknowledges the pain and violence faced by millions during the displacement. Declared by the Prime Minister of India in 2021.", month = 8, day = 14),
            DayEntity(title = "Pakistan Independence Day", category = "Historical", description = "A neighboring-country historical date. Marks the day Pakistan achieved independence and was declared a sovereign state following the end of the British Raj. Observed a day before India's independence.", month = 8, day = 14),
            DayEntity(title = "Independence Day of India", category = "National (India)", description = "India gained independence from British rule. One of the most important dates in Indian history (1947). Essential for polity, freedom struggle, and national identity.", month = 8, day = 15),
            DayEntity(title = "World Photography Day", category = "Cultural", description = "Celebrates photography as an art, medium, and historical innovation. Commemorates the invention of the Daguerreotype process in 1839. Photography has radically changed how we record history.", month = 8, day = 19),
            DayEntity(title = "Sadbhavana Diwas", category = "National (India)", description = "Promotes communal harmony and peace. Marks the birth anniversary of former Prime Minister Rajiv Gandhi. Means 'Harmony Day' in English.", month = 8, day = 20),
