            DayEntity(title = "World Hindi Day", category = "Cultural", description = "Important for language and cultural awareness. Marks the anniversary of the first World Hindi Conference held in 1975. Promotes the Hindi language globally.", month = 1, day = 10),
            DayEntity(title = "Lal Bahadur Shastri Death Anniversary", category = "Historical", description = "A major Indian political history date. Remembers the second Prime Minister of India, who died in Tashkent in 1966. He signed the Tashkent Declaration resolving the 1965 war.", month = 1, day = 11),
            DayEntity(title = "Lohri", category = "Cultural", description = "A major harvest festival in North India. Marks the end of winter and is a traditional welcome of longer days. Associated with lighting bonfires and dancing.", month = 1, day = 13),
            DayEntity(title = "Makar Sankranti / Pongal / Magh Bihu", category = "Cultural", description = "One of the most important festival dates in January. Marks the transition of the sun into the zodiac sign of Makara (Capricorn). Celebrated differently across India, like kite flying in Gujarat and Pongal in Tamil Nadu.", month = 1, day = 14),
            DayEntity(title = "Indian Army Day", category = "National (India)", description = "Important defence and national remembrance day. Marks the day Gen. K. M. Cariappa became the first Indian Commander-in-Chief in 1949. Celebrated with parades at all Army Command headquarters.", month = 1, day = 15),
            DayEntity(title = "National Startup Day", category = "Economy", description = "Important for innovation and entrepreneurship. Declared to encourage the startup ecosystem in India. First celebrated in 2022.", month = 1, day = 16),
            DayEntity(title = "Kokborok Day", category = "Cultural", description = "Important for regional language and cultural identity in Tripura. Recognizes the Kokborok language. Observed primarily in Tripura.", month = 1, day = 19),
            DayEntity(title = "State Foundation Day (Tripura, Manipur, Meghalaya)", category = "National (India)", description = "Very important for state formation history. These states attained full statehood under the North Eastern Region (Re-organisation) Act, 1971. Celebrated by all three states on the same day.", month = 1, day = 21),
            DayEntity(title = "National Girl Child Day", category = "National (India)", description = "Aims to raise awareness about the inequalities faced by girls. Initiated by the Ministry of Women and Child Development in 2008. Focuses on female education, health, and nutrition.", month = 1, day = 24),
            DayEntity(title = "National Tourism Day", category = "National (India)", description = "Raises awareness about the importance of tourism. Highlights the impact of tourism on the economy. India's rich cultural heritage makes it a major tourist destination.", month = 1, day = 25),
            DayEntity(title = "International Customs Day", category = "International", description = "Recognizes the role of custom officials. Commemorates the inaugural session of the World Customs Organization in 1953. Promotes international trade and border security.", month = 1, day = 26),
            DayEntity(title = "International Holocaust Remembrance Day", category = "Historical", description = "Remembers the victims of the Holocaust. Marks the liberation of the Auschwitz-Birkenau concentration camp in 1945. A UN observance urging every member nation to honor the victims of the Nazi era.", month = 1, day = 27),
            DayEntity(title = "Data Privacy Day", category = "Technology", description = "Important for digital rights. Raises awareness and promotes privacy and data protection best practices. Also known as Data Protection Day in Europe.", month = 1, day = 28)
        )

        val currentDays = dayDao.getAllDays().first()
        if (currentDays.isEmpty()) {
            dayDao.insertDays(initialData)
        }

        val db = Firebase.firestore
        try {
            val result = db.collection("days").get().await()
            val freshDays = dayDao.getAllDays().first()

            val documents = result.documents
            for (doc in documents) {
                val title = doc.getString("title") ?: continue
                val desc = doc.getString("description") ?: continue

                val existingDay = freshDays.find { it.title == title }
                if (existingDay != null && existingDay.description != desc) {
                    dayDao.updateDay(existingDay.copy(description = desc))
                }
            }
        } catch (e: Exception) {
            e.printStackTrace()

        }
    }
}
